// Cloudflare Worker entry (T-39): the OpenNext app plus a cron trigger.
// `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import handler from "./.open-next/worker.js";

const worker = {
  fetch: handler.fetch,

  /** Every 15 minutes (wrangler.jsonc "triggers"): send due daily check-in reminders. */
  async scheduled(_controller, env, ctx) {
    const request = new Request("https://zdoma.internal/api/cron/opomniki", {
      method: "POST",
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(
      handler
        .fetch(request, env, ctx)
        .then(async (res) => console.log("opomniki", res.status, await res.text()))
        .catch((err) => console.error("opomniki failed", err)),
    );
  },
};

export default worker;
